import { RiAddLine, RiAsterisk, RiDropLine, RiMenLine, RiStethoscopeLine } from "@remixicon/react";
import type { ComponentType } from "react";
import { Avatar } from "../../base/avatar/avatar";
import { Button } from "../../base/buttons/button";
import { CardSurface } from "../charts/card-surface";
import { cx } from "../../utils/cx";

/** Patient summary assembled from the shared avatar, button and card surface. */

type IconComponent = ComponentType<{
  className?: string;
  "aria-hidden"?: boolean | "true" | "false";
}>;

export type PatientDetail = { icon: IconComponent; label: string; value: string };

export const PATIENT_DETAILS: PatientDetail[] = [
  { icon: RiAsterisk, label: "Date of Birth", value: "14 March, 1994" },
  { icon: RiMenLine, label: "Gender", value: "Male" },
  { icon: RiDropLine, label: "Blood Type", value: "A rh+" },
  { icon: RiStethoscopeLine, label: "GP Doctor", value: "Alex Reed" },
];

export interface PatientInfoCardProps {
  className?: string;
  name?: string;
  initials?: string;
  details?: PatientDetail[];
  onAddPhoto?: () => void;
}
export function PatientInfoCard({
  className,
  name = "Jordan Morgan",
  initials = "J",
  details = PATIENT_DETAILS,
  onAddPhoto,
}: PatientInfoCardProps = {}) {
  return (
    <CardSurface
      padding="none"
      className={cx(
        "flex h-[330px] w-full min-w-0 flex-col items-center gap-[15px] rounded-[20px] bg-background-secondary-default px-2.5 pt-6 pb-2.5",
        className,
      )}
    >
      <div className="relative">
        <Avatar size="lg" initials={initials} className="size-[66px] text-[24.75px]" />
        <Button
          onClick={onAddPhoto}
          variant="secondary"
          size="xs"
          iconOnly
          leadingIcon={RiAddLine}
          aria-label="Add profile photo"
          className="absolute -top-0.5 -right-0.5 rounded-full"
        />
      </div>
      <p className="text-title-2-medium whitespace-nowrap text-text-primary">{name}</p>
      <div className="flex w-full flex-1 flex-col gap-2.5">
        {details.map((detail) => (
          <div
            key={detail.label}
            className="flex w-full items-center justify-between rounded-2lg bg-background-inner-default px-2.5 py-2"
          >
            <div className="flex items-center gap-1.5">
              <detail.icon className="size-4 shrink-0 text-text-secondary" aria-hidden />
              <span className="text-body-regular whitespace-nowrap text-text-secondary">
                {detail.label}
              </span>
            </div>
            <span className="text-body-medium whitespace-nowrap text-text-primary">
              {detail.value}
            </span>
          </div>
        ))}
      </div>
    </CardSurface>
  );
}
